    "evidenceNote": "1990年7月、联合演出机构、林兆华导演、伏尔泰《中国孤儿》与《赵氏孤儿》的并置演出及前卫化空间处理，已由北京大学《外国文学》1991年文章、PAR 1993年专题及2003年林兆华采访交叉核验。完整演员表、舞美署名及节目单仍待进一步核档。 / The July 1990 date, joint producing theatres, Lin Zhaohua’s direction, juxtaposition of Voltaire’s The Chinese Orphan with The Orphan of Zhao, and avant-garde spatial treatment are cross-checked against the 1991 Foreign Literatures article, the 1993 PAR feature and Lin’s 2003 interview. A complete cast list, individual design credits and programme still require further archival verification. 本条目补充图片来自林兆华《导演小人书》所收作品资料图；图片用于档案展示，不替代外部版本考证。",
    "evidenceNote_en": "The July 1990 date, joint producing theatres, Lin Zhaohua’s direction, juxtaposition of Voltaire’s The Chinese Orphan with The Orphan of Zhao, and avant-garde spatial treatment are cross-checked against the 1991 Foreign Literatures article, the 1993 PAR feature and Lin’s 2003 interview. A complete cast list, individual design credits and programme still require further archival verification. The added image is reproduced from a work image included in Lin Zhaohua’s Director’s Memoir; it is used for archival display and does not replace version-level external verification.",
