    "playwright": "歌德 / Johann Wolfgang von Goethe",
    "premiere": "1994",
    "theatre": "中央实验话剧院合作 / Central Experimental Theatre collaboration",
    "cast": "娄乃鸣饰摩菲斯特；其余角色主要由中央实验话剧院演员担纲 / Lou Naiming played Mephistopheles; most other roles were performed by Central Experimental Theatre actors.",
    "design": "公开资料记录了高度可变的桥与双梯式空间，并出现吉普车、飞船/剪影等视觉元素。 / Contemporary documentation describes a highly transformable bridge-and-stair space, with a jeep and other striking visual elements.",
    "music": "现场电子琴、八音鼓、吉他与歌手；汪峰及鲍家街43号参与音乐。 / Live keyboard, percussion, guitar and singers; Wang Feng and No.43 Baojia Street contributed music.",
    "synopsis": "90年代先锋戏剧谱系中的重要作品。工作室资料与同期艺术资料均将其列入林兆华工作室代表性作品。",
    "synopsis_en": "A major production in Lin's 1990s experimental theatre trajectory. It is listed among the representative works associated with his Theatre Studio and contemporary theatre documentation.",
    "background": "目前公开档案可确认作品的基本编年与创作归属；更详细的排演背景、委约关系及版本差异需继续核档。",
    "bg_en": "Public sources establish the basic chronology and authorship; detailed production history, commissioning context and version differences require further archival verification.",
    "overseas": "德国演出商在北京观看后提出赴德国演出的计划；具体场次仍需节目单/剧院档案进一步核实。 / A German presenter reportedly sought to take the production to Germany after seeing it in Beijing; exact performances still require programme/theatre-archive verification.",
    "revivals": "当前档案未完成复排版本的系统核档。 / Revival history is not yet systematically verified.",
    "reviews": "1994年《表演艺术》同期文章把该作描述为中国首次将歌德《浮士德》搬上舞台，并强调摇滚音乐与非写实空间带来的强烈现场感。 / A 1994 PAR article described it as the first Chinese staging of Goethe’s Faust and highlighted the rock music and non-realistic stage space.",
