    "desc": "2006年林兆华戏剧工作室制作的易卜生百年纪念项目。剧本由挪威剧作家约瑟夫·哈勒创作，林兆华执导，古飞德（Frede Gulbrandsen）任副导演；作品从《玩偶之家》三个孩子的视角重新讲述娜拉出走之后的故事。",
    "endesc": "A 2006 production by the Lin Zhaohua Theatre Studio for the Ibsen centenary. Written by Norwegian playwright Jesper Halle and directed by Lin Zhaohua, with Frede Gulbrandsen as associate director, it retells the aftermath of A Doll’s House from the perspective of Nora’s three children.",
    "quote": "2006年是世界大文豪、挪威剧作家易卜生逝世100周年……《娜拉的儿女》由林兆华戏剧工作室制作。",
