    "synopsis_en": "After Nora leaves in A Doll’s House, her three children have grown into young adults. The play revisits their childhood and family relationships from their perspective while drawing the audience into the theatrical situation.",
    "background": "2006年易卜生逝世100周年纪念活动中的戏剧项目，由林兆华戏剧工作室制作，在北京人艺实验剧场演出。公开资料对林兆华的职务表述略有差异：主创名单明确列其为导演，另有同期报道称他兼任戏剧顾问并与挪威导演古飞德合作；本档案以主创名单的“导演：林兆华”为作品导演字段。",
    "bg_en": "Produced by the Lin Zhaohua Theatre Studio for the 2006 Ibsen centenary and staged at the Beijing People’s Art Theatre Experimental Theatre. Contemporary sources vary in describing Lin’s role; the production credit list explicitly names him as director, while another report describes him as theatrical adviser working with Norwegian director Frede Gulbrandsen. This archive uses the explicit production credit for the director field.",
