    "venue": "北京人民艺术剧院首都剧场 / Capital Theatre, Beijing People’s Art Theatre",
    "creator": "孟冰 / Meng Bing（改编自陈忠实原著）",
    "director": "林兆华 / Lin Zhaohua",
    "desc": "将跨越半个世纪的长篇小说压缩为舞台作品，吸收陕西老腔、方言、农民演员与羊群等非传统话剧资源，形成高度地方化的舞台声音。",
    "endesc": "A stage adaptation of Chen Zhongshi's epic novel, using Shaanxi folk vocal traditions, dialect, local performers and even sheep to create a strongly localized theatrical language.",
    "quote": "这是我创作经历上前所未有的，也是最困难的一个戏。",
    "q_en": "“This was unprecedented in my creative life, and one of my most difficult productions.”",
