    "design": "林兆华与易立明在导演/灯光等职责上进行角色互换；舞台以古罗马城墙与现代摇滚现场并置 / Lin and Yi Liming exchanged directing/lighting responsibilities; Roman walls were juxtaposed with a contemporary rock-concert setting",
    "music": "痛仰、窒息等重金属摇滚乐队参与演出 / Rock bands including Miserable Faith and Suffocating participated",
    "synopsis": "围绕罗马将军科利奥兰纳斯的英雄主义、阶级冲突与政治处境展开。 / It explores Coriolanus’s heroism, class conflict and political predicament.",
    "synopsis_en": "A Shakespearean Roman tragedy staged with contemporary rock music and large-scale physical scenes. The production later toured to the Edinburgh International Festival in 2013.",
    "background": "英若诚2001年完成译本；林兆华希望将古典文本与现代人的社会历史处境连接起来。 / Ying Ruocheng completed the Chinese translation in 2001; Lin sought to connect the classical text with contemporary social and historical experience.",
