    "bg_en": "A later work in Guo Shixing’s “Dignity Trilogy,” continuing the collaborators’ focus on ordinary life, dignity and social relations.",
    "theatre": "天津滨湖剧院；后赴北京保利剧院 / Tianjin Binhai Theatre; later Beijing Poly Theatre",
